                .andExpect(jsonPath("$.releaseSnapshots.length()").value(1))
                .andExpect(jsonPath("$.releaseSnapshots[0].releasedBy").value("carol"));
    }

    @Test
    void readingAtExactDeviationIsNotOutlier() throws Exception {
        createCert("INS-B");
        createBatch("B-1", "INS-B", "10", "0.5");
