        release("REQ-L-3", "dave");
        mvc.perform(get("/api/batches/{key}", "B-1"))
                .andExpect(jsonPath("$.releaseSnapshots.length()").value(2))
                .andExpect(jsonPath("$.releaseSnapshots[1].batchRevision").value(2));
