                            .contentType(MediaType.APPLICATION_JSON)
                            .content("""
                                    {"requestId":"REQ-RV-%s","reviewer":"%s","decision":"ACCEPT",
                                     "reason":"可接受","batchRevision":1,"certificateVersion":1}
                                    """.formatted(reviewer, reviewer)))
                    .andExpect(status().isCreated());
